package com.dy.artisan3d.ui.screen.main.article.listimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport artisan3d.composeapp.generated.resources.Resimport artisan3d.composeapp.generated.resources.error_unknownimport com.dy.artisan3d.data.AppLanguageimport com.dy.artisan3d.domain.model.NetworkErrorimport com.dy.artisan3d.domain.repository.ArtisanArticleRepositoryimport com.dy.artisan3d.util.toErrorMessageimport kotlinx.coroutines.asyncimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.flow.updateimport kotlinx.coroutines.launchclass ArticleListViewModel(    private val appLange: AppLanguage,    private val artisanArticleRepository: ArtisanArticleRepository,) : ViewModel() {    private val _uiState = MutableStateFlow(ArticleListUiState())    val uiState = _uiState.asStateFlow()    init {        fetchHomeData()    }    fun fetchHomeData(isRefresh: Boolean = false) {        // Agar allaqachon yuklangan bo'lsa va bu refresh bo'lmasa - so'rov yubormaymiz        if (!isRefresh && _uiState.value.isInitialized) return        viewModelScope.launch {            _uiState.update { it.copy(isLoading = true) }            try {                val articlesDeferred = async { artisanArticleRepository.getArticles(1, appLange.current) }                val article = articlesDeferred.await().getOrThrow()                _uiState.update {                    it.copy(                        articles = article,                        isLoading = false,                        isInitialized = true,                        isError = false                    )                }            } catch (e: Exception) {                val errorMsg = if (e is NetworkError) {                    e.toErrorMessage()                } else {                    Res.string.error_unknown                }                _uiState.update {                    it.copy(                        isLoading = false,                        isError = true,                        errorMessage = errorMsg,                        isInitialized = true                    )                }            }        }    }}